begin;
select no_plan();
insert into public.profiles(id) values('00000000-0000-4000-8000-000000001721'),('00000000-0000-4000-8000-000000001722');
select * from public.operational_access_set('00000000-0000-4000-8000-000000001721','owner','grant','test:wait-erasure','Owner fixture','test:wait-erasure',null);
select public.mail_record_consent(null,'wait@example.invalid','pt-BR',true,'verified_waitlist',true);
select public.mail_record_consent('00000000-0000-4000-8000-000000001722','account@example.invalid','es',true,'verified_settings',false);
select throws_ok($$select public.mail_admin_execute('00000000-0000-4000-8000-000000001722','mail_forget_waitlist','{"email":"wait@example.invalid","confirm":true}','sandbox')$$,'42501','native_admin_forbidden','waitlist erasure requires Owner');
select throws_ok($$select public.mail_admin_execute('00000000-0000-4000-8000-000000001721','mail_forget_waitlist','{"email":"wait@example.invalid","confirm":false}','sandbox')$$,'P0001','native_admin_invalid','waitlist erasure requires explicit confirmation');
select lives_ok($$select public.mail_admin_execute('00000000-0000-4000-8000-000000001721','mail_forget_waitlist','{"email":"wait@example.invalid","confirm":true}','sandbox')$$,'Owner erases waitlist-only contact');
select is((select count(*)::integer from private.mail_contacts where email='wait@example.invalid'),0,'waitlist PII removed locally');
select is((select count(*)::integer from private.mail_contact_erasures where email='wait@example.invalid'),1,'provider erasure durably queued');
select lives_ok($$select public.mail_forget_waitlist('wait@example.invalid')$$,'signed-link retry is idempotent');
select is((select count(*)::integer from private.mail_contact_erasures where email='wait@example.invalid'),1,'duplicate forget never creates another job');
select throws_ok($$select public.mail_forget_waitlist('account@example.invalid')$$,'22023','mail_contact_has_account','waitlist link cannot erase an account contact');
select is((select consent from private.mail_contacts where email='account@example.invalid'),true,'wrong-route forget does not mutate account consent');
select ok(not has_function_privilege('anon','public.mail_forget_waitlist(text)','execute'),'public cannot forget arbitrary addresses through SQL');
select ok(not has_function_privilege('authenticated','public.mail_forget_waitlist(text)','execute'),'OAuth client cannot choose another address');
select * from finish();
rollback;
